import java.util.*;

public class Main {
    static final int MAXN = 505;
    static int n, m, mod;
    static int[] fact = new int[MAXN * 4];
    static int[] invFact = new int[MAXN * 4];
    static List<Integer> polyF = new ArrayList<>();
    static List<Integer> gPoly = new ArrayList<>();

    static int modWrap(int x) {
        if (x < 0) return x + mod;
        if (x >= mod) return x - mod;
        return x;
    }

    static void updateVal(int[] x, int y) {
        x[0] = modWrap(x[0] + y);
    }

    static int fastExponentiation(int base, int exp) {
        int res = 1;
        while (exp != 0) {
            if ((exp & 1) != 0) res = (int) ((long) res * base % mod);
            base = (int) ((long) base * base % mod);
            exp >>= 1;
        }
        return res;
    }

    static void precomputeFactorials(int n) {
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (int) ((long) fact[i - 1] * i % mod);
        }
        invFact[n] = fastExponentiation(fact[n], mod - 2);
        for (int i = n - 1; i >= 0; i--) {
            invFact[i] = (int) ((long) invFact[i + 1] * (i + 1) % mod);
        }
    }

    static int choose(int n, int m) {
        if (n < 0 || m < 0 || n < m) return 0;
        return (int) ((long) fact[n] * invFact[n - m] % mod * invFact[m] % mod);
    }

    static int sumSeries(int x) {
        return x * (x + 1) / 2;
    }

    static List<Integer> multiplyPoly(List<Integer> A, List<Integer> B) {
        int sizeA = A.size();
        int sizeB = B.size();
        List<Integer> C = new ArrayList<>(Collections.nCopies(sizeA + sizeB - 1, 0));
