                int[] cVal = new int[]{C.get(i + j)};
                updateVal(cVal, val);
                C.set(i + j, cVal[0]);
            }
        }
        return C;
    }

    static int G(int n, int m) {
        return choose(m + n - 1, n - 1);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        m = sc.nextInt();
        n = sc.nextInt();
        mod = sc.nextInt();

        precomputeFactorials(m << 1);

        polyF.clear();
        gPoly.clear();

        for (int i = 0; i <= n; i++) {
            polyF.add(0);
            gPoly.add(0);
        }

        polyF.set(0, 1);
        for (int i = 1; i <= n; i++) {
            int val = 0;
            for (int j = 0; j < i; j++) {
                int temp = (int) ((long) polyF.get(j) * polyF.get(i - 1 - j) % mod);
                temp = (int) ((long) temp * choose(i - 1, j) % mod);
                val = (int) ((long) val + temp) % mod;
            }
            val = (int) ((long) val * (i + 1) % mod);
            polyF.set(i, val);
        }

        for (int i = 1; i <= n; i++) {
            int sumSeriesJ = sumSeries(i - 1);
            int sumSeriesJMinus = sumSeries(i - 1);
            int val = 0;
            for (int j = 0; j < i; j++) {
                int term1 = (2L * polyF.get(j) * gPoly.get(i - 1 - j) % mod) * choose(i - 1, j) % mod;
                term1 = term1 * (i + 1) % mod;
                int term2 = (int) ((long) choose(i - 1, j) * (sumSeriesJ + sumSeriesJMinus) % mod * polyF.get(j) % mod * polyF.get(i - 1 - j) % mod);
                val = (int) ((val + term1 + term2) % mod);
            }
            gPoly.set(i, val);
        }

        gPoly.set(0, 0);
        for (int i = 0; i <= n; i++) {
            gPoly.set(i, (int) ((long) gPoly.get(i) * invFact[i] % mod));
            polyF.set(i, (int) ((long) polyF.get(i) * invFact[i] % mod));
        }

        int totalAns = 0;
        for (int i = 1; i <= m - n + 1; i++) {
            int temp = (int) ((long) gPoly.get(n) * G(i + 1, m - n - i + 1) % mod);
            temp = (int) ((long) temp * fact[n] % mod);
            temp = (int) ((long) temp * i % mod);
            totalAns = (int) ((totalAns + temp) % mod);
            gPoly = multiplyPoly(gPoly, polyF);
            gPoly = gPoly.subList(0, n + 1);
